// Days in each month of a year that is not a leap year.
constexpr std::array<int, 12> kMonthDays = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

constexpr std::array<int, 13> make_days_before() {
    std::array<int, 13> t{};
    for (std::size_t m = 0; m < kMonthDays.size(); ++m) {
        t[m + 1] = t[m] + kMonthDays[m];
    }
    return t;
}

constexpr std::array<int, 13> kDaysBefore = make_days_before();
static_assert(kDaysBefore[2] == 59, "January and February");
static_assert(kDaysBefore[12] == 365, "a whole year");

int day_of_year(int month, int day) {
    return kDaysBefore[month - 1] + day;
}

int main() {
