#include <cmath>
#include <cstdint>
#include <iostream>
#include <type_traits>

template <typename T, std::enable_if_t<std::is_integral_v<T>, int> = 0>
bool is_on_grid(T price, T tick) {
    return price % tick == 0;
}

template <typename T, std::enable_if_t<std::is_floating_point_v<T>, int> = 0>
bool is_on_grid(T price, T tick) {
    const T steps = price / tick;
    return std::abs(steps - std::round(steps)) < 1e-9;
}

int main() {
    int64_t price_ticks = 0;
    int64_t tick_ticks = 0;
    double price = 0.0;
    double tick = 0.0;
    std::cin >> price_ticks >> tick_ticks >> price >> tick;
    std::cout << std::boolalpha;
    std::cout << price_ticks << " on a grid of " << tick_ticks << ": "
              << is_on_grid(price_ticks, tick_ticks) << '\n';
    std::cout << price << " on a grid of " << tick << ": " << is_on_grid(price, tick) << '\n';
    return 0;
}

steps.body:
A pricing library prices many payoffs with the same model. Write the model once as a template and pass the payoff as a type, a **policy**: a small struct whose `operator()` is the one piece that varies. Each payoff is a function object, like the comparators in the operator overloading lesson:

```cpp
struct Call {
    double operator()(double S, double K) const { return std::max(S - K, 0.0); }
};

struct Put {
    double operator()(double S, double K) const { return std::max(K - S, 0.0); }
};

// One step of a binomial tree: the stock ends 10% up or 10% down, each with
// probability 1/2, which are the risk-neutral odds when rates are zero.
template <typename Payoff>
double price(const Payoff& p, double S, double K) {
    return 0.5 * (p(S * 1.1, K) + p(S * 0.9, K));
}
std::cout << price(Call{}, 100.0, 95.0) << ' ' << price(Put{}, 100.0, 95.0) << '\n';  // 7.5 2.5
```

`Call{}` is a brace-initialized temporary of an empty struct. It holds no data, and `sizeof(Call)` is 1, the least any object can take. Its only job is its type, which makes it a **tag**. The compiler deduces `Payoff = Call` and stamps out `price<Call>`, the template's *specialization* for that one payoff, where `p(...)` is a direct call to `Call::operator()` that it can inline.

Here is `price(Call{}, S, K)` from g++ 10.2 at `-O2`. No `Call` object and no call are left, just the two scenarios, a subtract each, and `maxsd`, the larger of two doubles:

```text
_Z10price_calldd:
        movsd   xmm2, QWORD PTR .LC1[rip]   # 1.1
        pxor    xmm3, xmm3                  # 0.0
        movapd  xmm4, xmm3
        mulsd   xmm2, xmm0                  # S * 1.1
        mulsd   xmm0, QWORD PTR .LC2[rip]   # S * 0.9
        subsd   xmm2, xmm1                  # - K
        subsd   xmm0, xmm1
        maxsd   xmm4, xmm2                  # max(..., 0.0)
        maxsd   xmm3, xmm0
        movapd  xmm0, xmm3
        addsd   xmm0, xmm4
        mulsd   xmm0, QWORD PTR .LC3[rip]   # * 0.5
        ret
```

`price(Put{}, S, K)` compiles to a function of its own with `K - S` in place of `S - K`. One generic model, one fully specialized function per payoff. If one payoff ever needs a different algorithm, write it by hand as an explicit specialization, `template <> double price<Digital>(const Digital& p, double S, double K)`, and only that payoff uses it.

example.code:
#include <algorithm>
#include <iomanip>
#include <iostream>

struct Call {
    double operator()(double S, double K) const { return std::max(S - K, 0.0); }
};

struct Put {
    double operator()(double S, double K) const { return std::max(K - S, 0.0); }
};

// One step of a binomial tree: the stock ends 10% up or 10% down, each with
// probability 1/2, which are the risk-neutral odds when rates are zero.
template <typename Payoff>
double price(const Payoff& p, double S, double K) {
    return 0.5 * (p(S * 1.1, K) + p(S * 0.9, K));
}

int main() {
    std::cout << "sizeof(Call) = " << sizeof(Call) << '\n';
    std::cout << std::fixed << std::setprecision(4);
    const double S = 100.0;
    for (double K : {95.0, 100.0, 105.0}) {
        const double call = price(Call{}, S, K);
        const double put = price(Put{}, S, K);
        std::cout << "K " << K << " call " << call << " put " << put
                  << " call - put " << call - put << '\n';
    }
    return 0;
}

